using System.IO.Compression;
using System.Text.Json;
using Avalonia;
namespace WirePulse;

/// Portable ZIP with a versioned, camelCase manifest. Never exports credentials or platform preferences.
public sealed class LayoutPackage {
 public string Format{get;set;}="wirepulse-layout";public int Version{get;set;}=1;
 public SceneDocument Scene{get;set;}=new();public bool Snap{get;set;}=true;
 public BackgroundLayout Background{get;set;}=new();
 public sealed class BackgroundLayout{public string Color{get;set;}="#000000";public string Asset{get;set;}="";public double Dim{get;set;}public GradientSpec? Gradient{get;set;}}
 public static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,PropertyNameCaseInsensitive=true,WriteIndented=true};
 const long Limit=2L*1024*1024*1024;const int FileLimit=2048;
 public void Apply(Settings settings){settings.Scene=Scene.Clone();settings.Gradients=Background.Gradient is{} g?new(){["backgroundcolor"]=g.Clean()}:[];settings.EditorSnap=Snap;settings.Values["backgroundcolor"]=System.Text.Json.Nodes.JsonValue.Create(Background.Color);settings.Values["backgroundimage"]=System.Text.Json.Nodes.JsonValue.Create(Background.Asset);settings.Values["dim"]=System.Text.Json.Nodes.JsonValue.Create(Background.Dim);settings.Save();}
 static string Relative(string name){if(string.IsNullOrWhiteSpace(name)||name.Contains('\\')||name.Contains(':')||name.StartsWith('/')||name.Split('/').Any(p=>p is ".." or "."))throw new InvalidDataException("Ruta no válida en el layout.");return name;}
 static string AssetRoot(string path){var file=Path.GetFullPath(path);var root=Path.GetFullPath(AssetStore.Root)+Path.DirectorySeparatorChar;if(file.StartsWith(root,StringComparison.Ordinal)){var parts=Path.GetRelativePath(root,file).Split(Path.DirectorySeparatorChar);int nested=Array.FindLastIndex(parts,p=>p=="assets");return Path.Combine(root,Path.Combine(parts.Take(nested>=0?nested+2:1).ToArray()));}return Path.GetDirectoryName(file)!;}
 public static LayoutPackage Create(Settings settings,Size viewport)=>new(){Scene=settings.Scene?.Clone()??SceneDocument.Migrate(settings,viewport),Snap=settings.EditorSnap,Background=new(){Color=settings.Text("backgroundcolor"),Asset=settings.Text("backgroundimage"),Dim=settings.N("dim"),Gradient=settings.Gradient("backgroundcolor")}};
 public static void Export(string target,Settings settings,Size viewport)=>Export(target,Create(settings,viewport));
 public static void Export(string target,LayoutPackage package){package=JsonSerializer.Deserialize<LayoutPackage>(JsonSerializer.Serialize(package,Json),Json)!;var stage=Path.Combine(Path.GetTempPath(),"wirepulse-layout-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);string temporary=Path.GetFullPath(target)+".tmp-"+Guid.NewGuid().ToString("N");try{var specs=new Settings("layout-export").Specs;foreach(var item in package.Scene.Items){string group=item.Kind switch{"orb"=>"Orbe","spectrum"=>"Espectro","card"=>"Tarjeta","clock"=>"Reloj","stars" or "mesh"=>"Fondo animado",_=>""};var keys=specs.Where(s=>s.Group==group&&!EditorWindow.LayoutKeys.Contains(s.Key)&&s.Kind is not("image" or "file")).Select(s=>s.Key).ToHashSet();item.Style=item.Style.Where(p=>keys.Contains(p.Key)).ToDictionary(p=>p.Key,p=>p.Value);}
  var imported=new Dictionary<string,string>();long total=0;int count=0;
  string Include(string source,bool widget=false){if(string.IsNullOrWhiteSpace(source))return "";source=Path.GetFullPath(source);if(imported.TryGetValue(source,out var existing))return existing;string asset="assets/"+Guid.NewGuid().ToString("N")+"/";
   void Copy(string file,string name){Relative(name);var info=new FileInfo(file);if((info.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("El layout contiene enlaces.");total+=info.Length;if(total>Limit||++count>FileLimit)throw new InvalidDataException("Layout demasiado grande (máximo 2 GB / 2048 archivos).");string dest=Path.Combine(stage,name.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(file,dest);}
   string result;if(widget){string root=AssetRoot(source);void Walk(string directory){foreach(var entry in Directory.EnumerateFileSystemEntries(directory)){var attributes=File.GetAttributes(entry);if((attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("El widget contiene enlaces.");if((attributes&FileAttributes.Directory)!=0)Walk(entry);else Copy(entry,asset+Path.GetRelativePath(root,entry).Replace('\\','/'));}}Walk(root);result=asset+Path.GetRelativePath(root,source).Replace('\\','/');}else{result=asset+Path.GetFileName(source);Copy(source,result);}imported[source]=result;return result;}
  foreach(var item in package.Scene.Items){if(item.Kind is "image" or "widget")item.Asset=Include(item.Asset,item.Kind=="widget");else item.Asset="";}
  package.Background.Asset=Include(package.Background.Asset);File.WriteAllText(Path.Combine(stage,"layout.json"),JsonSerializer.Serialize(package,Json));ZipFile.CreateFromDirectory(stage,temporary,CompressionLevel.Fastest,false);using(var check=ZipFile.OpenRead(temporary)){if(check.Entries.Count>FileLimit)throw new InvalidDataException("Demasiadas entradas en el layout.");}File.Move(temporary,target,true);
 }finally{Directory.Delete(stage,true);if(File.Exists(temporary))File.Delete(temporary);}}
 public static LayoutPackage Import(string source,string? destinationRoot=null){string folder=Path.Combine(destinationRoot??AssetStore.Root,"layout-"+Guid.NewGuid().ToString("N"));try{using var zip=ZipFile.OpenRead(source);if(zip.Entries.Count>FileLimit)throw new InvalidDataException("Demasiados archivos en el layout.");long total=0;var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in zip.Entries){string name=Relative(entry.FullName);if(!names.Add(name)||((entry.ExternalAttributes>>16)&0xF000)==0xA000)throw new InvalidDataException("Layout con rutas duplicadas o enlaces.");total+=entry.Length;if(total>Limit)throw new InvalidDataException("El layout supera 2 GB.");}
  var manifest=zip.GetEntry("layout.json")??throw new InvalidDataException("Falta layout.json.");if(manifest.Length>2*1024*1024)throw new InvalidDataException("Manifiesto demasiado grande.");LayoutPackage package;using(var stream=manifest.Open())package=JsonSerializer.Deserialize<LayoutPackage>(stream,Json)??throw new InvalidDataException("Layout vacío.");if(package.Format!="wirepulse-layout"||package.Version!=1||package.Scene==null||package.Background==null)throw new InvalidDataException("Versión de layout no compatible.");if(package.Scene.Items.Count>256||package.Scene.Items.Any(i=>!SceneDocument.SceneKinds.Contains(i.Kind)||new[]{i.X,i.Y,i.Width,i.Height,i.Rotation,i.Opacity}.Any(n=>!double.IsFinite(n))))throw new InvalidDataException("Objeto de layout inválido.");package.Scene.Sanitize();if(!Avalonia.Media.Color.TryParse(package.Background.Color,out _))throw new InvalidDataException("Color de fondo no válido.");package.Background.Dim=double.IsFinite(package.Background.Dim)?Math.Clamp(package.Background.Dim,0,100):0;
  var specs=new Settings("layout-validation").Specs;foreach(var item in package.Scene.Items){foreach(var spec in specs){if(!item.Style.TryGetValue(spec.Key,out var value))continue;if(spec.Kind=="slider"){if(value is not System.Text.Json.Nodes.JsonValue n||!n.TryGetValue<double>(out var number)||!double.IsFinite(number))throw new InvalidDataException("Propiedad numérica inválida.");item.Style[spec.Key]=System.Text.Json.Nodes.JsonValue.Create(Math.Clamp(number,spec.Min,spec.Max));}else if(spec.Kind=="color"&&!Avalonia.Media.Color.TryParse(value?.ToString(),out _))throw new InvalidDataException("Color de objeto inválido.");}}
  Directory.CreateDirectory(folder);zip.ExtractToDirectory(folder);
  string Resolve(string asset){if(asset.Length==0)return "";Relative(asset);if(!asset.StartsWith("assets/",StringComparison.Ordinal))throw new InvalidDataException("Recurso fuera de assets/.");string result=Path.GetFullPath(Path.Combine(folder,asset.Replace('/',Path.DirectorySeparatorChar)));if(!result.StartsWith(folder+Path.DirectorySeparatorChar,StringComparison.Ordinal)||!File.Exists(result))throw new InvalidDataException("Recurso ausente en el layout.");return result;}
  foreach(var item in package.Scene.Items)item.Asset=item.Kind is "image" or "widget"?Resolve(item.Asset):"";package.Background.Asset=Resolve(package.Background.Asset);return package;
 }catch{if(Directory.Exists(folder))Directory.Delete(folder,true);throw;}}
}
